import React, { useState } from "react";
import {
  GraduationCap,
  Briefcase,
  BarChart3,
  UserCheck,
  Zap,
  ArrowRight,
  CheckCircle2,
  Mail,
  Menu,
  CalendarDays,
  User,
  X,
  LogOut,
  Settings,
  Bell,
  Search,
  Sun,
  Moon,
  Award,
  MessageCircle,
  Calendar,
  Star,
  ChevronUp
} from 'lucide-react';

const neonColor = "#00D9FF";
const neonBorder = "border-cyan-400";
const neonText = "text-cyan-400";
const neonBg = "bg-cyan-400/10";
const neonGlow = "shadow-cyan-400/25";

const profilePic = "https://randomuser.me/api/portraits/men/32.jpg";

const menuTabs = [
  { name: "MAILS", icon: Mail },
  { name: "EVENTS", icon: CalendarDays },
  { name: "PROFILE", icon: User },
  { name: "ACHIEVEMENTS", icon: Award },
  { name: "CHAT", icon: MessageCircle }
];

const mails = [
  { subject: "Internship Offer", from: "Google", time: "1h ago", unread: true },
  { subject: "Interview Reminder", from: "Amazon", time: "Yesterday", unread: false },
  { subject: "Profile Update", from: "CampusConnect", time: "2 days ago", unread: false }
];

const events = [
  { title: "Amazon Interview", date: "2025-09-25", time: "10:00 AM", location: "Room 201" },
  { title: "Career Fair", date: "2025-09-28", time: "2:00 PM", location: "Main Hall" }
];

const achievements = [
  { title: "Dean's List", desc: "Top 5% of students", icon: Star, color: "text-yellow-400" },
  { title: "Hackathon Winner", desc: "CampusConnect Hackathon 2025", icon: Award, color: "text-emerald-400" },
  { title: "Internship at Google", desc: "Software Engineering Intern", icon: Briefcase, color: neonText }
];

const mentorMessages = [
  { from: "Ms. Smith", message: "Congrats on your internship!", time: "10 min ago" },
  { from: "Mr. Lee", message: "Let's schedule a meeting.", time: "Yesterday" }
];

const notifications = [
  { text: "New internship posted!", time: "2m ago" },
  { text: "Mentor replied to your message.", time: "1h ago" }
];

const StudentDash = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activeTab, setActiveTab] = useState(menuTabs[0].name);
  const [theme, setTheme] = useState("dark");
  const [showNotifications, setShowNotifications] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  // Scroll-to-top button visibility
  React.useEffect(() => {
    const onScroll = () => setShowScrollTop(window.scrollY > 300);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Responsive sidebar for mobile
  const sidebarClasses = `fixed top-0 left-0 h-full w-72 bg-gray-900/95 border-r-2 ${neonBorder} ${neonGlow} z-40 transform transition-transform duration-300
    ${drawerOpen ? "translate-x-0" : "-translate-x-full"} md:translate-x-0 md:static md:w-64 md:h-auto md:bg-transparent md:border-none md:shadow-none`;

  return (
    <div className={`${theme === "dark" ? "bg-gray-900 text-white" : "bg-white text-gray-900"} min-h-screen relative font-sans transition-colors duration-500`}>
      {/* Sticky Navbar */}
      <nav className="sticky top-0 z-50 w-full flex items-center justify-between px-4 md:px-8 py-3 bg-gray-900/80 border-b border-gray-800 shadow-lg">
        <div className="flex items-center space-x-3">
          <GraduationCap className={`h-7 w-7 ${neonText} drop-shadow-lg`} />
          <span className={`font-bold text-xl ${neonText}`}>CampusConnect</span>
        </div>
        <div className="flex items-center space-x-3">
          <button className="p-2 rounded-xl bg-gray-800 hover:bg-gray-700 transition relative" onClick={() => setShowNotifications(!showNotifications)}>
            <Bell className="h-6 w-6 text-cyan-400" />
            {notifications.length > 0 && (
              <span className="absolute top-1 right-1 bg-cyan-400 text-gray-900 rounded-full px-2 py-0.5 text-xs font-bold">{notifications.length}</span>
            )}
          </button>
          <button className="p-2 rounded-xl bg-gray-800 hover:bg-gray-700 transition" onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>
            {theme === "dark" ? <Sun className="h-6 w-6 text-yellow-300" /> : <Moon className="h-6 w-6 text-gray-700" />}
          </button>
          <button className="p-2 rounded-xl bg-gray-800 hover:bg-gray-700 transition">
            <Settings className="h-6 w-6 text-cyan-400" />
          </button>
          <div className="relative">
            <button
              className="flex items-center space-x-2"
              onClick={() => setShowProfileMenu(!showProfileMenu)}
            >
              <img
                src={profilePic}
                alt="Profile"
                className={`h-9 w-9 rounded-full border-2 ${neonBorder} ${neonGlow} object-cover`}
              />
              <span className="font-semibold hidden md:inline">John Doe</span>
            </button>
            {showProfileMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-gray-900 border border-cyan-400 rounded-xl shadow-xl z-50">
                <button className="w-full text-left px-4 py-3 hover:bg-gray-800 transition">View Profile</button>
                <button className="w-full text-left px-4 py-3 hover:bg-gray-800 transition">Settings</button>
                <button className="w-full text-left px-4 py-3 hover:bg-gray-800 transition">Logout</button>
              </div>
            )}
          </div>
          <button
            className={`p-2 rounded-xl border-2 ${neonBorder} ${neonGlow} bg-gray-800 hover:bg-gray-700 transition md:hidden`}
            onClick={() => setDrawerOpen(true)}
            aria-label="Open menu"
          >
            <Menu className={`h-6 w-6 ${neonText}`} />
          </button>
        </div>
      </nav>

      {/* Notifications Dropdown */}
      {showNotifications && (
        <div className="fixed right-4 top-16 z-40 bg-gray-900 border border-cyan-400 rounded-xl shadow-xl w-80">
          <div className="p-4 border-b border-gray-800 font-bold text-cyan-400">Notifications</div>
          <ul>
            {notifications.map((n, idx) => (
              <li key={idx} className="px-4 py-3 border-b border-gray-800 flex items-center">
                <Bell className="h-5 w-5 mr-2 text-cyan-400" />
                <span className="flex-1">{n.text}</span>
                <span className="text-xs text-gray-400">{n.time}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Responsive Sidebar */}
      <aside className={sidebarClasses}>
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800 md:hidden">
          <div className="flex items-center space-x-3">
            <img
              src={profilePic}
              alt="Profile"
              className={`h-9 w-9 rounded-full border-2 ${neonBorder} ${neonGlow} object-cover`}
            />
            <span className={`font-semibold text-lg ${neonText}`}>John Doe</span>
          </div>
          <button
            className="p-2 rounded-lg hover:bg-gray-800 transition"
            onClick={() => setDrawerOpen(false)}
            aria-label="Close menu"
          >
            <X className="h-6 w-6 text-gray-400" />
          </button>
        </div>
        <div className="flex flex-col px-6 py-6 space-y-2">
          {menuTabs.map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.name}
                className={`flex items-center w-full px-4 py-3 rounded-xl font-semibold text-left transition-all duration-200
                  ${activeTab === tab.name ? `${neonBg} ${neonText} border-2 ${neonBorder}` : "text-gray-300 hover:bg-gray-800"}
                `}
                onClick={() => { setActiveTab(tab.name); setDrawerOpen(false); }}
              >
                <Icon className={`h-5 w-5 mr-3 ${activeTab === tab.name ? neonText : "text-gray-400"}`} />
                {tab.name}
              </button>
            );
          })}
        </div>
        <div className="px-6 py-4 border-t border-gray-800 mt-auto">
          <button className="w-full py-2 rounded-xl bg-gradient-to-r from-cyan-400 to-emerald-400 text-gray-900 font-bold shadow-lg hover:scale-105 transition flex items-center justify-center gap-2">
            <LogOut className="h-5 w-5" />
            Logout
          </button>
        </div>
      </aside>
      {/* Overlay for drawer */}
      {drawerOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/40 md:hidden"
          onClick={() => setDrawerOpen(false)}
        />
      )}

      {/* Main Content */}
      <main className="relative z-10 min-h-screen flex flex-col items-center px-2 md:px-6 py-6 md:py-12 transition-all duration-300">
        {/* Floating Action Button (FAB) */}
        <button className="fixed bottom-8 right-8 z-50 bg-gradient-to-r from-cyan-400 to-emerald-400 text-gray-900 rounded-full shadow-lg p-4 hover:scale-110 transition md:hidden">
          <Zap className="h-7 w-7" />
        </button>

        {/* Header */}
        <div className="max-w-3xl w-full mb-8 md:mb-10">
          <div className="flex items-center space-x-4 mb-6">
            <div className={`p-4 bg-gray-800 border-2 ${neonBorder} rounded-2xl ${neonGlow}`}>
              <GraduationCap className="h-12 w-12" style={{ color: neonColor }} />
            </div>
            <h1 className="text-3xl md:text-4xl font-bold bg-gradient-to-r from-cyan-400 via-emerald-400 to-orange-400 bg-clip-text text-transparent animate-pulse">
              Welcome, Student!
            </h1>
          </div>
          <p className="text-base md:text-lg text-gray-300">
            Your personalized dashboard for internships, progress, and campus updates.
          </p>
        </div>

        {/* Responsive Stats Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6 md:gap-8 w-full max-w-5xl mb-8 md:mb-12">
          <div className={`bg-gray-800/90 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 flex flex-col items-center shadow-xl`}>
            <Briefcase className="h-8 w-8 md:h-10 md:w-10 mb-2 md:mb-3" style={{ color: neonColor }} />
            <h2 className={`text-lg md:text-2xl font-bold mb-1 md:mb-2 ${neonText}`}>Internships Applied</h2>
            <p className="text-2xl md:text-4xl font-bold text-white mb-1">7</p>
            <span className="text-gray-400 text-xs md:text-base">This semester</span>
          </div>
          <div className={`bg-gray-800/90 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 flex flex-col items-center shadow-xl`}>
            <BarChart3 className="h-8 w-8 md:h-10 md:w-10 mb-2 md:mb-3" style={{ color: neonColor }} />
            <h2 className={`text-lg md:text-2xl font-bold mb-1 md:mb-2 ${neonText}`}>Progress</h2>
            <p className="text-2xl md:text-4xl font-bold text-white mb-1">85%</p>
            <span className="text-gray-400 text-xs md:text-base">Profile completed</span>
          </div>
          <div className={`bg-gray-800/90 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 flex flex-col items-center shadow-xl`}>
            <UserCheck className="h-8 w-8 md:h-10 md:w-10 mb-2 md:mb-3" style={{ color: neonColor }} />
            <h2 className={`text-lg md:text-2xl font-bold mb-1 md:mb-2 ${neonText}`}>Mentor Meetings</h2>
            <p className="text-2xl md:text-4xl font-bold text-white mb-1">3</p>
            <span className="text-gray-400 text-xs md:text-base">Upcoming</span>
          </div>
        </div>

        {/* Responsive Tabbed Content */}
        <div className="w-full max-w-4xl mb-8 md:mb-12">
          <div className={`bg-gray-800/80 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-4 md:p-8 shadow-lg`}>
            <div className="flex flex-wrap items-center mb-4 md:mb-6 gap-2">
              {menuTabs.map(tab => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.name}
                    className={`flex items-center px-3 py-2 rounded-xl font-semibold mr-2 transition-all duration-200
                      ${activeTab === tab.name ? `${neonBg} ${neonText} border-2 ${neonBorder}` : "text-gray-300 hover:bg-gray-800"}
                    `}
                    onClick={() => setActiveTab(tab.name)}
                  >
                    <Icon className={`h-5 w-5 mr-2 ${activeTab === tab.name ? neonText : "text-gray-400"}`} />
                    <span className="text-xs md:text-base">{tab.name}</span>
                  </button>
                );
              })}
            </div>
            {/* Tab Content */}
            {activeTab === "MAILS" && (
              <div>
                <div className="flex items-center mb-4">
                  <Search className="h-5 w-5 text-gray-400 mr-2" />
                  <input
                    type="text"
                    placeholder="Search mails..."
                    className="bg-gray-900 border border-gray-700 rounded-xl px-3 py-2 text-gray-200 w-full focus:outline-none focus:border-cyan-400"
                  />
                </div>
                <ul className="divide-y divide-gray-800">
                  {mails.map((mail, idx) => (
                    <li key={idx} className="py-3 md:py-4 flex items-center">
                      <Mail className={`h-6 w-6 mr-3 ${mail.unread ? neonText : "text-gray-400"}`} />
                      <div className="flex-1">
                        <span className={`font-bold ${mail.unread ? neonText : "text-gray-200"}`}>{mail.subject}</span>
                        <span className="ml-2 text-gray-400">from {mail.from}</span>
                      </div>
                      <span className="text-xs text-gray-500">{mail.time}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {activeTab === "EVENTS" && (
              <div>
                <ul className="space-y-4">
                  {events.map((event, idx) => (
                    <li key={idx} className="flex items-center justify-between bg-gray-900/60 rounded-xl p-4 border border-cyan-900">
                      <div>
                        <span className={`font-bold text-lg ${neonText}`}>{event.title}</span>
                        <div className="text-gray-400 text-sm">{event.date} • {event.time}</div>
                        <div className="text-gray-500 text-xs">{event.location}</div>
                      </div>
                      <CalendarDays className={`h-8 w-8 ${neonText}`} />
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {activeTab === "PROFILE" && (
              <div>
                <form className="space-y-4 md:space-y-6 max-w-md">
                  <div>
                    <label className="block text-gray-400 mb-1">Full Name</label>
                    <input type="text" defaultValue="John Doe" className="w-full px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  </div>
                  <div>
                    <label className="block text-gray-400 mb-1">Email</label>
                    <input type="email" defaultValue="john.doe@college.edu" className="w-full px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  </div>
                  <div>
                    <label className="block text-gray-400 mb-1">Major</label>
                    <input type="text" defaultValue="Computer Science" className="w-full px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  </div>
                  <button type="submit" className={`w-full py-3 rounded-xl bg-gradient-to-r from-cyan-400 to-emerald-400 text-gray-900 font-bold shadow-lg hover:scale-105 transition`}>
                    Save Changes
                  </button>
                </form>
              </div>
            )}
            {activeTab === "ACHIEVEMENTS" && (
              <div>
                <ul className="space-y-4">
                  {achievements.map((ach, idx) => {
                    const Icon = ach.icon;
                    return (
                      <li key={idx} className="flex items-center bg-gray-900/60 rounded-xl p-4 border border-cyan-900">
                        <Icon className={`h-8 w-8 mr-4 ${ach.color}`} />
                        <div>
                          <span className="font-bold text-lg text-cyan-400">{ach.title}</span>
                          <div className="text-gray-400 text-sm">{ach.desc}</div>
                        </div>
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}
            {activeTab === "CHAT" && (
              <div>
                <ul className="space-y-4">
                  {mentorMessages.map((msg, idx) => (
                    <li key={idx} className="flex items-center bg-gray-900/60 rounded-xl p-4 border border-cyan-900">
                      <MessageCircle className="h-6 w-6 mr-3 text-cyan-400" />
                      <div>
                        <span className="font-bold text-cyan-400">{msg.from}</span>
                        <div className="text-gray-300">{msg.message}</div>
                        <div className="text-xs text-gray-500">{msg.time}</div>
                      </div>
                    </li>
                  ))}
                </ul>
                <form className="mt-6 flex items-center gap-2">
                  <input type="text" placeholder="Type a message..." className="flex-1 px-4 py-2 rounded-xl bg-gray-900 border border-gray-700 text-gray-200 focus:outline-none focus:border-cyan-400" />
                  <button type="submit" className={`py-2 px-4 rounded-xl bg-gradient-to-r from-cyan-400 to-emerald-400 text-gray-900 font-bold shadow-lg hover:scale-105 transition`}>
                    Send
                  </button>
                </form>
              </div>
            )}
          </div>
        </div>

        {/* Recent Activity */}
        <div className="w-full max-w-3xl mb-8 md:mb-12">
          <div className={`bg-gray-800/80 rounded-2xl border-2 ${neonBorder} ${neonGlow} p-6 shadow-lg`}>
            <h3 className={`text-xl font-bold mb-4 ${neonText}`}>Recent Activity</h3>
            <ul className="space-y-4">
              <li className="flex items-center">
                <CheckCircle2 className="h-5 w-5 mr-3" style={{ color: neonColor }} />
                <span className="text-gray-300">Applied to <span className={neonText}>Google Summer Internship</span></span>
                <span className="ml-auto text-xs text-gray-500">2 days ago</span>
              </li>
              <li className="flex items-center">
                <CheckCircle2 className="h-5 w-5 mr-3" style={{ color: neonColor }} />
                <span className="text-gray-300">Scheduled interview with <span className={neonText}>Amazon</span></span>
                <span className="ml-auto text-xs text-gray-500">Yesterday</span>
              </li>
              <li className="flex items-center">
                <CheckCircle2 className="h-5 w-5 mr-3" style={{ color: neonColor }} />
                <span className="text-gray-300">Profile updated</span>
                <span className="ml-auto text-xs text-gray-500">Just now</span>
              </li>
            </ul>
          </div>
        </div>

        {/* Scroll-to-top Button */}
        {showScrollTop && (
          <button
            className="fixed bottom-20 right-8 z-50 bg-cyan-400 text-gray-900 rounded-full shadow-lg p-3 hover:scale-110 transition"
            onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
            aria-label="Scroll to top"
          >
            <ChevronUp className="h-6 w-6" />
          </button>
        )}

        {/* Footer */}
        <footer className="border-t border-gray-800 bg-gray-900/50 backdrop-blur-sm py-8 w-full mt-auto">
          <div className="text-center">
            <div className="flex justify-center items-center space-x-4 mb-4">
              <div className="h-px w-16 bg-gradient-to-r from-transparent to-cyan-400"></div>
              <span className="text-gray-400 font-medium">SECURE • RELIABLE • FAST</span>
              <div className="h-px w-16 bg-gradient-to-l from-transparent to-emerald-400"></div>
            </div>
            <p className="text-gray-500">
              Need help?{' '}
              <button className="text-cyan-400 hover:text-cyan-300 font-semibold transition-colors duration-300">
                support@campusconnect.edu
              </button>
            </p>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default StudentDash;
